// Title: Programmatically add a comment to a cell, export the workbook to HTML with comments enabled, and verify the comment using Aspose.Cells for .NET
// Common Searches: how to add a cell comment and export it to HTML using Aspose.Cells C# | Aspose.Cells HtmlSaveOptions export comments example | verify exported comment text in HTML file generated by Aspose.Cells | C# save workbook as HTML with comments included Aspose.Cells | read HTML output to check for specific cell comment Aspose.Cells
// Tags: Aspose.Cells add comment to cell | HtmlSaveOptions IsExportComments setting | Aspose.Cells comment export configuration | C# read generated HTML for comment verification | save workbook to HTML with annotations Aspose.Cells

using System;
using System.IO;
using Aspose.Cells;

// The example creates a new Workbook, inserts a comment into cell A1, enables comment export via HtmlSaveOptions.IsExportComments, saves the workbook as HTML, reads the resulting file, and confirms that the comment text is present in the HTML output.
class Program
{
    static void Main()
    {
        // Create a new workbook
        Workbook workbook = new Workbook();

        // Get the first worksheet
        Worksheet sheet = workbook.Worksheets[0];

        // Add a comment to cell A1 (row 0, column 0)
        int row = 0;
        int col = 0;
        int commentIndex = sheet.Comments.Add(row, col);
        Comment comment = sheet.Comments[commentIndex];
        comment.Note = "This is a test comment";
        comment.Author = "AsposeUser";

        // Configure HTML save options to export comments
        HtmlSaveOptions htmlOptions = new HtmlSaveOptions();
        htmlOptions.IsExportComments = true;

        // Save the workbook as HTML
        string htmlFile = "output.html";
        workbook.Save(htmlFile, htmlOptions);

        // Verify that the comment text appears in the generated HTML
        string htmlContent = File.ReadAllText(htmlFile);
        if (htmlContent.Contains("This is a test comment"))
        {
            Console.WriteLine("Comment successfully exported to HTML.");
        }
        else
        {
            Console.WriteLine("Comment not found in HTML.");
        }
    }
}
